-- Variables
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

local inFocusOpacity = 1
local notInFocusOpacity = 1

hl.window_rule({
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

-- Fix some dragging issues with XWayland
hl.window_rule({
    match = {
        class = "^$",
        title = "^$",
        xwayland = 1,
        float = 1,
        fullscreen = 0,
        pin = 0,
    },
    no_focus = true,
})

-- Default opacity for all windows
hl.window_rule({
    match = {
        class = ".*",
    },
    opacity = inFocusOpacity .. " " .. notInFocusOpacity,
})

-- Kitty fully opaque
hl.window_rule({
    match = {
        class = "^kitty$",
    },
    opacity = "1 1",
})

-- Browsers
hl.window_rule({
    match = {
        class = "^(firefox|brave|chromium|librewolf|qutebrowser|zen-browser)$",
    },
    opacity = inFocusOpacity .. " " .. notInFocusOpacity,
})

-- Spotify / Discord / Telegram / VS Code / Thunar or Nemo by title
hl.window_rule({
    match = {
        title = ".*Spotify.*",
    },
    opacity = inFocusOpacity .. " " .. notInFocusOpacity,
})

hl.window_rule({
    match = {
        title = ".*Discord.*",
    },
    opacity = inFocusOpacity .. " " .. notInFocusOpacity,
})

hl.window_rule({
    match = {
        title = ".*Telegram.*",
    },
    opacity = inFocusOpacity .. " " .. notInFocusOpacity,
})

hl.window_rule({
    match = {
        title = ".*Code.*",
    },
    opacity = inFocusOpacity .. " " .. notInFocusOpacity,
})

hl.window_rule({
    match = {
        title = ".*(Thunar|nemo).*",
    },
    opacity = inFocusOpacity .. " " .. notInFocusOpacity,
})

-- Lunar Client fullscreen (static effect)
hl.window_rule({
    match = {
        class = "^Lunar Client.*$",
    },
    fullscreen = true,
})

